css:
/* Apply global font & layout */
.print-format {
    font-family: "Times New Roman", serif;
    font-size: 12pt;
    line-height: 1.6;
    color: #000;
}

/* Format the generated letter field */
#generated_letter {
    white-space: pre-wrap; /* preserve line breaks from text */
    text-align: justify;
    margin-top: 15px;
    margin-bottom: 20px;
}

/* Optional: make heading more formal */
.print-heading {
    font-size: 16pt;
    font-weight: bold;
    text-align: center;
    margin-bottom: 25px;
}

/* Hide field labels for generated_letter (if you want a clean look) */
#generated_letter ~ .label {
    display: none;
}

/* Make page A4 friendly */
@page {
    size: A4;
    margin: 25mm;
}

html:
{# resolve linked docs safely #}
{% set sender_doc = frappe.get_doc("Employee", doc.sender) if doc.sender else None %}
{% set company_doc = frappe.get_doc("Company", doc.company) if doc.company else None %}

<div class="letter-wrap">
  <div class="letter-meta" style="text-align:right">
    {{ frappe.utils.formatdate(doc.get('date') or doc.creation, "yyyy/MM/dd") }}
  </div>

  <div class="from">
    به نام خدا<br>
    فرستنده:
    {{ _(sender_doc.employee_name) if sender_doc else "" }}
    {{ _(sender_doc.designation) if sender_doc else "" }}<br>
    {{ _(sender_doc.current_address) if sender_doc else "" }}
  </div>

  <div class="to" style="margin-top:10px">
    شرکت:
    {{ _(company_doc.company_name) if company_doc else "" }}<br>
    مالک/صاحب امتیاز:
    {{ _(company_doc.owner) if company_doc else "" }}
  </div>

  <div class="subject" style="margin:12px 0;font-weight:bold">
    موضوع: {{ _(doc.get('letter_name')) }}
  </div>

  <div class="body" style="text-align:justify; white-space:pre-wrap">
    {{ (_(doc.get('generated_letter')) or '') | safe }}
    {# if it's plain text, use nl2br instead of safe:  | nl2br #}
  </div>

  <div class="sig" style="margin-top:36px">
    {{ _(sender_doc.employee_name) if sender_doc else "" }}<br>
    {{ _(sender_doc.designation) if sender_doc else "" }}
  </div>
</div>
